-- Dadyoom Grade 1-3 original supplementary text-linked exercises: ترتيب الأحداث, 66 safe lesson IDs.
-- The independently authored reading passages reside in each activity's content.originalText (visible to the learner).
-- No ministry source equivalence, audio delivery, or teacher sign-off is inferred. Existing learner attempts are preserved.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='90s';
CREATE TEMP TABLE g123_sequence_activities ON COMMIT DROP AS
SELECT grade::int,activity_order::int,activity_type::text,title::text,section::text,prompt::text,content::jsonb,answer::jsonb
FROM jsonb_to_recordset($passage$[{"grade":1,"activity_order":4,"activity_type":"fill_blank","title":"تطبيق موجه على النص","section":"practice","prompt":"ماذا فعلت ليلى بعد أن رأت الورقة على الأرض؟","content":{"origin":"DADYOOM_G123_SEQUENCE_198_ORIGINAL_20261030","originalText":"خرجت ليلى إلى حديقة المدرسة صباحًا، فرأت ورقةً على الأرض. التقطت الورقة، ثم وضعتها في سلة المهملات. بعد ذلك غسلت يديها، وشكرها المعلم على المحافظة على نظافة الحديقة. حدثت هذه الخطوات واحدة بعد الأخرى، وللقصة بداية ووسط ونهاية.","didacticGrade":1,"scope":"original supplementary reading","items":[{"sentence":"بعد أن رأت ليلى الورقة، قامت بـ ___.","options":["التقاطها","قراءة كتاب","زراعة شجرة"]}]},"answer":{"answers":["التقاطها"]}},{"grade":1,"activity_order":5,"activity_type":"matching","title":"توصيل المفهوم بالدليل","section":"practice","prompt":"اقرأ النص الإثرائي ثم صِل كل عبارة بما تمثله من حدث أو معلومة أو وظيفة.","content":{"origin":"DADYOOM_G123_SEQUENCE_198_ORIGINAL_20261030","originalText":"خرجت ليلى إلى حديقة المدرسة صباحًا، فرأت ورقةً على الأرض. التقطت الورقة، ثم وضعتها في سلة المهملات. بعد ذلك غسلت يديها، وشكرها المعلم على المحافظة على نظافة الحديقة. حدثت هذه الخطوات واحدة بعد الأخرى، وللقصة بداية ووسط ونهاية.","didacticGrade":1,"scope":"original supplementary reading","left":["رأت ليلى ورقة على الأرض.","وضعت الورقة في السلة.","غسلت يديها وشكرها المعلم."],"right":["النهاية","البداية","الوسط"]},"answer":{"pairs":[{"left":"رأت ليلى ورقة على الأرض.","right":"البداية"},{"left":"وضعت الورقة في السلة.","right":"الوسط"},{"left":"غسلت يديها وشكرها المعلم.","right":"النهاية"}]}},{"grade":1,"activity_order":6,"activity_type":"multiple_choice","title":"تقييم الفهم والاستنتاج","section":"assessment","prompt":"أيّ حدث وقع قبل أن تغسل ليلى يديها؟","content":{"origin":"DADYOOM_G123_SEQUENCE_198_ORIGINAL_20261030","originalText":"خرجت ليلى إلى حديقة المدرسة صباحًا، فرأت ورقةً على الأرض. التقطت الورقة، ثم وضعتها في سلة المهملات. بعد ذلك غسلت يديها، وشكرها المعلم على المحافظة على نظافة الحديقة. حدثت هذه الخطوات واحدة بعد الأخرى، وللقصة بداية ووسط ونهاية.","didacticGrade":1,"scope":"original supplementary reading","options":["وضعت الورقة في سلة المهملات.","شكرها المعلم ثم رأت الورقة.","ذهبت إلى المنزل ثم بدأت القصة."]},"answer":{"correct":"وضعت الورقة في سلة المهملات."}},{"grade":2,"activity_order":4,"activity_type":"fill_blank","title":"تطبيق موجه على النص","section":"practice","prompt":"ما الخطوة التي جاءت بعد سؤال نور أمينة المكتبة؟","content":{"origin":"DADYOOM_G123_SEQUENCE_198_ORIGINAL_20261030","originalText":"في صباح الثلاثاء، أحضرت نور ثلاث قصص إلى ركن القراءة. اكتشفت أن القصص غير مرتبة حسب الموضوع، فسألت أمينة المكتبة عن أفضل طريقة لتنظيمها. وضعت قصص الطبيعة في رف، وقصص الرحلات في رف آخر، ثم وضعت بطاقات أسماء على الرفوف. بعد نهاية الفسحة، استطاع زملاؤها العثور على القصة المطلوبة بسهولة. بدأ الحدث بمشكلة، ثم جاء الحل وظهرت نتيجته.","didacticGrade":2,"scope":"original supplementary reading","items":[{"sentence":"بعد أن سألت نور أمينة المكتبة، ___ القصص حسب الموضوع.","options":["رتبت","أحرقت","مزقت"]}]},"answer":{"answers":["رتبت"]}},{"grade":2,"activity_order":5,"activity_type":"matching","title":"توصيل المفهوم بالدليل","section":"practice","prompt":"اقرأ النص الإثرائي ثم صِل كل عبارة بما تمثله من حدث أو معلومة أو وظيفة.","content":{"origin":"DADYOOM_G123_SEQUENCE_198_ORIGINAL_20261030","originalText":"في صباح الثلاثاء، أحضرت نور ثلاث قصص إلى ركن القراءة. اكتشفت أن القصص غير مرتبة حسب الموضوع، فسألت أمينة المكتبة عن أفضل طريقة لتنظيمها. وضعت قصص الطبيعة في رف، وقصص الرحلات في رف آخر، ثم وضعت بطاقات أسماء على الرفوف. بعد نهاية الفسحة، استطاع زملاؤها العثور على القصة المطلوبة بسهولة. بدأ الحدث بمشكلة، ثم جاء الحل وظهرت نتيجته.","didacticGrade":2,"scope":"original supplementary reading","left":["اكتشفت نور أن القصص غير مرتبة.","صنفت نور القصص ووضعت أسماء على الرفوف.","وجد الطلاب القصص المطلوبة بسهولة."],"right":["النتيجة","المشكلة الأولى","الإجراء الأوسط"]},"answer":{"pairs":[{"left":"اكتشفت نور أن القصص غير مرتبة.","right":"المشكلة الأولى"},{"left":"صنفت نور القصص ووضعت أسماء على الرفوف.","right":"الإجراء الأوسط"},{"left":"وجد الطلاب القصص المطلوبة بسهولة.","right":"النتيجة"}]}},{"grade":2,"activity_order":6,"activity_type":"multiple_choice","title":"تقييم الفهم والاستنتاج","section":"assessment","prompt":"ما ترتيب الأحداث الصحيح في النص؟","content":{"origin":"DADYOOM_G123_SEQUENCE_198_ORIGINAL_20261030","originalText":"في صباح الثلاثاء، أحضرت نور ثلاث قصص إلى ركن القراءة. اكتشفت أن القصص غير مرتبة حسب الموضوع، فسألت أمينة المكتبة عن أفضل طريقة لتنظيمها. وضعت قصص الطبيعة في رف، وقصص الرحلات في رف آخر، ثم وضعت بطاقات أسماء على الرفوف. بعد نهاية الفسحة، استطاع زملاؤها العثور على القصة المطلوبة بسهولة. بدأ الحدث بمشكلة، ثم جاء الحل وظهرت نتيجته.","didacticGrade":2,"scope":"original supplementary reading","options":["استعارة القصص، ثم ملاحظة الفوضى، ثم ترتيب الرفوف.","ملاحظة عدم الترتيب، ثم تصنيف القصص، ثم سهولة العثور عليها.","سهولة العثور على القصص، ثم سؤال أمينة المكتبة، ثم اكتشاف الفوضى."]},"answer":{"correct":"ملاحظة عدم الترتيب، ثم تصنيف القصص، ثم سهولة العثور عليها."}},{"grade":3,"activity_order":4,"activity_type":"fill_blank","title":"تطبيق موجه على النص","section":"practice","prompt":"ما الذي فعلَه سالم بعد ملاحظة المشكلة وقبل تغيير طريقة العناية؟","content":{"origin":"DADYOOM_G123_SEQUENCE_198_ORIGINAL_20261030","originalText":"في حديقة المدرسة، لاحظ سالم أن بعض الشتلات تذبل رغم سقيها يوميًا. لم يغيّر كمية الماء فورًا؛ بل سأل معلمة العلوم، ولاحظ أن التربة تحت الشتلات لا تصرف الماء جيدًا. بالتعاون مع زملائه حسّن تصريف التربة ووضع جدولًا معتدلًا للسقي، ثم راقب الأوراق لمدة أسبوع. بدأت الشتلات تستعيد عافيتها. سجّل سالم المشكلة والملاحظة والخطوات والنتيجة؛ لأن تقديم النتيجة قبل وصف الإجراءات يضعف تفسير السبب.","didacticGrade":3,"scope":"original supplementary reading","items":[{"sentence":"قبل تعديل العناية، سأل سالم ___ ولاحظ التربة.","options":["معلمة العلوم","عامل المكتبة","حارس البوابة"]}]},"answer":{"answers":["معلمة العلوم"]}},{"grade":3,"activity_order":5,"activity_type":"matching","title":"توصيل المفهوم بالدليل","section":"practice","prompt":"اقرأ النص الإثرائي ثم صِل كل عبارة بما تمثله من حدث أو معلومة أو وظيفة.","content":{"origin":"DADYOOM_G123_SEQUENCE_198_ORIGINAL_20261030","originalText":"في حديقة المدرسة، لاحظ سالم أن بعض الشتلات تذبل رغم سقيها يوميًا. لم يغيّر كمية الماء فورًا؛ بل سأل معلمة العلوم، ولاحظ أن التربة تحت الشتلات لا تصرف الماء جيدًا. بالتعاون مع زملائه حسّن تصريف التربة ووضع جدولًا معتدلًا للسقي، ثم راقب الأوراق لمدة أسبوع. بدأت الشتلات تستعيد عافيتها. سجّل سالم المشكلة والملاحظة والخطوات والنتيجة؛ لأن تقديم النتيجة قبل وصف الإجراءات يضعف تفسير السبب.","didacticGrade":3,"scope":"original supplementary reading","left":["لاحظ سالم ذبول الشتلات رغم السقي.","فحص تصريف التربة ثم عدّل السقي مع الفريق.","تحسنت الشتلات بعد أسبوع من المتابعة."],"right":["نتيجة التغيير","مرحلة اكتشاف المشكلة","مرحلة التحري والإجراء"]},"answer":{"pairs":[{"left":"لاحظ سالم ذبول الشتلات رغم السقي.","right":"مرحلة اكتشاف المشكلة"},{"left":"فحص تصريف التربة ثم عدّل السقي مع الفريق.","right":"مرحلة التحري والإجراء"},{"left":"تحسنت الشتلات بعد أسبوع من المتابعة.","right":"نتيجة التغيير"}]}},{"grade":3,"activity_order":6,"activity_type":"multiple_choice","title":"تقييم الفهم والاستنتاج","section":"assessment","prompt":"لماذا يجب ذكر فحص التربة وتعديل السقي قبل نتيجة تحسّن الشتلات؟","content":{"origin":"DADYOOM_G123_SEQUENCE_198_ORIGINAL_20261030","originalText":"في حديقة المدرسة، لاحظ سالم أن بعض الشتلات تذبل رغم سقيها يوميًا. لم يغيّر كمية الماء فورًا؛ بل سأل معلمة العلوم، ولاحظ أن التربة تحت الشتلات لا تصرف الماء جيدًا. بالتعاون مع زملائه حسّن تصريف التربة ووضع جدولًا معتدلًا للسقي، ثم راقب الأوراق لمدة أسبوع. بدأت الشتلات تستعيد عافيتها. سجّل سالم المشكلة والملاحظة والخطوات والنتيجة؛ لأن تقديم النتيجة قبل وصف الإجراءات يضعف تفسير السبب.","didacticGrade":3,"scope":"original supplementary reading","options":["لإظهار كيف أدى الإجراء إلى النتيجة.","لأن التحسن وقع قبل اكتشاف المشكلة.","لأن أحداث القصة ليس لها ترتيب زمني."]},"answer":{"correct":"لإظهار كيف أدى الإجراء إلى النتيجة."}}]$passage$::jsonb)
AS x(grade int,activity_order int,activity_type text,title text,section text,prompt text,content jsonb,answer jsonb);
DO $safe$
DECLARE candidates int; safe_candidates int; protected_count int; inserted int;
BEGIN
 IF (SELECT count(*) FROM pg_temp.g123_sequence_activities)<>9 OR
    (SELECT count(DISTINCT (grade,activity_order)) FROM pg_temp.g123_sequence_activities)<>9 OR
    EXISTS(SELECT 1 FROM pg_temp.g123_sequence_activities WHERE activity_type IS NULL OR answer IS NULL OR length(content->>'originalText')<150)
 THEN RAISE EXCEPTION 'Invalid nine source-linked grade-specific templates'; END IF;
 WITH found AS (
  SELECT l.id,count(a.id) FILTER(WHERE a.is_published) n,
    count(DISTINCT a.activity_order) positions,max(a.activity_order) max_order
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
  LEFT JOIN public.lesson_activities a ON a.lesson_id=l.id
  WHERE l.title='ترتيب الأحداث' AND l.status='published' AND g.grade_number BETWEEN 1 AND 3 AND l.content LIKE '%ترتيب الأحداث%' AND l.content LIKE '%البداية%'
  GROUP BY l.id
 )
 SELECT count(*) INTO candidates FROM found WHERE n=3 AND positions=3 AND max_order=3;
 IF candidates<>66 THEN RAISE EXCEPTION 'Expected 66 original lesson IDs with three existing activities, found %',candidates; END IF;
 SELECT count(*) INTO protected_count FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 WHERE l.title='ترتيب الأحداث' AND l.status='published' AND g.grade_number BETWEEN 1 AND 3 AND l.content LIKE '%ترتيب الأحداث%' AND l.content LIKE '%البداية%' AND NOT (NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id) AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities la ON la.id=at.activity_id WHERE la.lesson_id=l.id) AND NOT EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id));
 IF protected_count<>0 THEN RAISE EXCEPTION 'Protected learner-history count drift, expected 0, found %', protected_count; END IF;
 SELECT count(*) INTO safe_candidates FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 WHERE l.title='ترتيب الأحداث' AND l.status='published' AND g.grade_number BETWEEN 1 AND 3 AND l.content LIKE '%ترتيب الأحداث%' AND l.content LIKE '%البداية%' AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id) AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities la ON la.id=at.activity_id WHERE la.lesson_id=l.id) AND NOT EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id);
 IF safe_candidates<>66 THEN RAISE EXCEPTION 'Expected 66 safe lesson IDs, got %',safe_candidates; END IF;
 IF EXISTS (SELECT 1 FROM public.lesson_activities a WHERE a.content->>'origin'='DADYOOM_G123_SEQUENCE_198_ORIGINAL_20261030')
 THEN RAISE EXCEPTION 'Batch DADYOOM_G123_SEQUENCE_198_ORIGINAL_20261030 already inserted'; END IF;
 INSERT INTO public.lesson_activities
  (lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
 SELECT l.id,t.title,t.activity_type,'اقرأ النص الإثرائي الموجود داخل النشاط؛ اقرأ محتوى درس بلدك مستقلًا.',
        t.content,t.activity_order,5,true,t.section,t.prompt,t.answer,false
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN pg_temp.g123_sequence_activities t ON t.grade=g.grade_number
 WHERE l.title='ترتيب الأحداث' AND l.status='published' AND g.grade_number BETWEEN 1 AND 3 AND l.content LIKE '%ترتيب الأحداث%' AND l.content LIKE '%البداية%' AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id) AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities la ON la.id=at.activity_id WHERE la.lesson_id=l.id) AND NOT EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>198 THEN RAISE EXCEPTION 'Atomic rollback: inserted % instead of 198',inserted; END IF;
 RAISE NOTICE 'DADYOOM_G123_SEQUENCE_198_ORIGINAL_20261030=%',inserted;
END $safe$;
COMMIT;
